-- Generated by Supabase CLI. New application only; independent date memo.
-- No backfill, formula, trigger, permission, billing or maintenance record updates.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $$ BEGIN
 IF (SELECT count(*) FROM public.ageful_migration_target)<>1 OR NOT EXISTS(
   SELECT 1 FROM public.ageful_migration_target WHERE project_ref='ufawaiddntqqbjhycbxn') THEN
  RAISE EXCEPTION 'Wrong project: maintenance date memo is for the new application only';
 END IF;
END $$;
DO $$ DECLARE before_hash text; after_hash text; BEGIN
 SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY id),'[]'::jsonb)::text) INTO before_hash FROM public.contracts c;
 ALTER TABLE public.contracts ADD COLUMN maintenance_period_start_memo_date date;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(c)-'maintenance_period_start_memo_date' ORDER BY id),'[]'::jsonb)::text) INTO after_hash FROM public.contracts c;
 IF before_hash IS DISTINCT FROM after_hash THEN RAISE EXCEPTION 'Existing contract data changed during memo migration'; END IF;
END $$;
COMMENT ON COLUMN public.contracts.maintenance_period_start_memo_date IS '保守期間開始日（独立した日付メモ）。請求・保守期間・自動予定の計算に使用しない。maintenance_start_date（保守契約開始日）とは別。初期値は空欄。';
NOTIFY pgrst, 'reload schema';
COMMIT;
